\set ON_ERROR_STOP on
\pset pager off

create or replace function pg_temp.assert_catalog(label text, actual jsonb, expected jsonb)
returns void language plpgsql as $$
begin
  if actual is distinct from expected then
    raise exception E'% divergiu da baseline verificada.\nEsperado: %\nObtido: %', label, jsonb_pretty(expected), jsonb_pretty(actual);
  end if;
  raise notice 'OK: %', label;
end;
$$;

